    }

    // ---- family 6: near the top of the range where 2.0f-max rounds ---
    for(int i=0;i<30000;i++){
        float mx=1.0f+u01(rng);          // [1,2)
        float mn=u01(rng)*2.f-1.f;
        emit(mx,mn,mn);
        float mx2=u01(rng);              // [0,1)
        emit(mx2,mn,mn);
    }

    // ---- family 7: raw random bit patterns (CLI-expressible only) ----
    for(int i=0;i<60000;i++){
        float a=fb(rng()), b2=fb(rng()), c=fb(rng());
        emit(a,b2,c);
    }

    // dedupe
    std::set<std::string> seen;
    for(auto&s:lines) if(seen.insert(s).second) printf("%s\n",s.c_str());
    fprintf(stderr,"emitted %zu unique of %zu\n", seen.size(), lines.size());
    return 0;
}
